import React from 'react';
import { motion } from 'framer-motion';

const posts = [
  {
    id: 1,
    category: 'Cloud Architecture',
    date: 'May 2026',
    title: 'Designing Scalable Systems for Product-Driven Teams',
    excerpt:
      'A practical framework for building resilient cloud platforms that keep product delivery fast and reliable.',
    image:
      'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=80',
  },
  {
    id: 2,
    category: 'DevOps',
    date: 'April 2026',
    title: 'Automating Release Pipelines Without Losing Control',
    excerpt:
      'How to create predictable deployment workflows that balance speed, quality, and team ownership.',
    image:
      'https://images.unsplash.com/photo-1517430816045-df4b7de54f10?auto=format&fit=crop&w=900&q=80',
  },
  {
    id: 3,
    category: 'Security',
    date: 'March 2026',
    title: 'Zero Trust for Modern Microservice Architectures',
    excerpt:
      'Key security principles for protecting distributed systems and reducing risk in production environments.',
    image:
      'https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=900&q=80',
  },
];

function BlogSection() {
  return (
    <section className="blog-section" id="blog">
      <div className="section-header">
        <span className="section-label">Latest Articles</span>
        <h2 className="section-title">Fresh thinking for modern engineering teams</h2>
      </div>

      <div className="blog-grid">
        {posts.map((post, index) => (
          <motion.article
            key={post.id}
            className="blog-card"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: index * 0.1 }}
          >
            <div className="blog-card-image">
              <img src={post.image} alt={post.title} />
            </div>
            <div className="blog-card-content">
              <div className="blog-card-meta">
                <span className="blog-category">{post.category}</span>
                <span className="blog-date">{post.date}</span>
              </div>
              <h3>{post.title}</h3>
              <p>{post.excerpt}</p>
              <a href="#contact" className="blog-readmore">
                Read article
              </a>
            </div>
          </motion.article>
        ))}
      </div>
    </section>
  );
}

export default BlogSection;
